import {HiddenUnicodeAlert} from '@github-ui/hidden-unicode-banner/HiddenUnicodeAlert'
import {LineNumberCell} from './LineNumberCell'
import {ContentCell} from './ContentCell'
import {DiffCodeAlert} from './DiffCodeAlert'
import type {SuggestedFixDiffLine} from '../../types/suggested-fix'

export type CodeDiffLineProps = {
  diffLine: SuggestedFixDiffLine
  hasHiddenUnicodeCharacters: boolean
  isLeftSide?: boolean
}

export const CodeDiffLine = ({diffLine, hasHiddenUnicodeCharacters, isLeftSide}: CodeDiffLineProps) => {
  /*
   * display the left cell for all lines in a unified view, and left lines of a split view
   * this cell will not contain a number in the unified view if the line is an addition
   */
  const showLeftNumber = diffLine.type !== 'ADDITION'
  const showLeftNumberCell = isLeftSide

  /*
   * display the right cell for all lines in a unified view, and right lines of a split view
   * this cell will not contain a number in the unified view if the line is a deletion
   */
  const showRightNumber = diffLine.type !== 'DELETION'
  const showRightNumberCell = !isLeftSide

  return (
    <>
      {showLeftNumberCell && (
        <LineNumberCell diffLine={diffLine} isLeftSide={isLeftSide}>
          {hasHiddenUnicodeCharacters && !showRightNumber && (
            <DiffCodeAlert>
              <HiddenUnicodeAlert />
            </DiffCodeAlert>
          )}
          {showLeftNumber && <>{diffLine.left}</>}
        </LineNumberCell>
      )}
      {showRightNumberCell && (
        <LineNumberCell diffLine={diffLine} isLeftSide={isLeftSide}>
          {hasHiddenUnicodeCharacters && showRightNumber && (
            <DiffCodeAlert>
              <HiddenUnicodeAlert />
            </DiffCodeAlert>
          )}
          {showRightNumber && <>{diffLine.right}</>}
        </LineNumberCell>
      )}
      <ContentCell diffLine={diffLine} isLeftSide={isLeftSide} />
    </>
  )
}
