import {useCallback, useMemo, useState} from 'react'
import type {AiFileFindings, AiFindingsSweAgentJob, ReadOnlyAiFindingsSweAgentJob} from '../types/ai-findings'
import {useCreateSweAgentJob} from './use-create-swe-agent-job'
import {useSweAgentJobQueries} from './use-swe-agent-job-queries'
import {generateAiFindingsFixPrompt} from '../utils/ai-findings-fix-prompt-generation'
import {shouldStopTrackingSweAgentJob} from '../utils/swe-agent-job-status-check'

type UseAiFindingsJobsOptions = {
  onError?: (error: Error) => void
  refetchInterval?: number
}

export function useAiFindingsJobs(owner: string, repo: string, branch: string, options: UseAiFindingsJobsOptions = {}) {
  const {onError, refetchInterval = 1000} = options
  const [localJobs, setLocalJobs] = useState<AiFindingsSweAgentJob[]>([])
  const [filesWithJobBeingCreated, setFilesWithJobBeingCreated] = useState<string[]>([])

  const createJobMutation = useCreateSweAgentJob({
    owner,
    repo,
  })

  const createJob = useCallback(
    async (fileFindings: AiFileFindings[]) => {
      const filePaths = fileFindings.map(file => file.filePath)
      setFilesWithJobBeingCreated(filePaths)

      try {
        const problemStatement = generateAiFindingsFixPrompt(fileFindings)
        const prTitle = `Fix code quality findings`

        const response = await createJobMutation.mutateAsync({
          problemStatement,
          prTitle,
          branch,
          // The event type identifies our integration to the SWE Agent service.
          eventType: 'code_quality_ai_findings',
        })

        const newJob: AiFindingsSweAgentJob = {
          job_id: response.job_id,
          status: 'pending',
          files: fileFindings,
        }
        setLocalJobs(prev => [...prev, newJob])

        return newJob
      } catch (error) {
        if (onError && error instanceof Error) {
          onError(error)
        }
      } finally {
        setFilesWithJobBeingCreated([])
      }
    },
    [createJobMutation, branch, onError],
  )

  const removeJob = useCallback((jobId: string) => {
    setLocalJobs(prev => prev.filter(job => job.job_id !== jobId))
  }, [])

  // Poll for updates to keep job status up to date. We always poll all jobs but
  // then let the query system handle whether to fetch or not based on the job status.
  const {queryResults} = useSweAgentJobQueries(
    owner,
    repo,
    localJobs.map(j => j.job_id),
    refetchInterval,
  )

  // Merge local jobs with query results to get the most up-to-date status
  const jobs = useMemo(
    () =>
      localJobs.map(job => {
        const queryResult = queryResults.find(result => result.data?.job_id === job.job_id)
        if (queryResult?.data) {
          return {...job, ...queryResult.data}
        }
        return job
      }),
    [localJobs, queryResults],
  )

  const isCreatingPr = useCallback(
    (filePaths: string[]) => {
      // Check if any of the specified files have a job being created for them
      if (filesWithJobBeingCreated.some(file => filePaths.includes(file))) {
        return true
      }

      // Check if any active job is processing any of the given file paths.
      return jobs
        .filter(job => !shouldStopTrackingSweAgentJob(job))
        .some(job => job.files.some(file => filePaths.includes(file.filePath)))
    },
    [filesWithJobBeingCreated, jobs],
  )

  return {
    jobs: jobs as readonly ReadOnlyAiFindingsSweAgentJob[],
    createJob,
    removeJob,
    isCreatingPr,
  }
}
