import {clsx} from 'clsx'
import type {ComponentPropsWithoutRef} from 'react'

export type CellProps = ComponentPropsWithoutRef<'td'> & {
  isLeftSide?: boolean
}

export function Cell({isLeftSide, className, children, ...props}: CellProps) {
  return (
    <td
      role="gridcell"
      valign="top"
      className={clsx(className, {
        'left-side': isLeftSide,
      })}
      {...props}
    >
      {children}
    </td>
  )
}
