// eslint-disable-next-line @github-ui/github-monorepo/restrict-relay-imports
import {getLineBackgroundColor} from '@github-ui/diff-lines'
import type {DiffLineType} from '@github-ui/diffs/types'
import {clsx} from 'clsx'
import type {ReactNode} from 'react'
import type {SuggestedFixDiffLine} from '../../types/suggested-fix'
import {Cell} from './Cell'

export type LineNumberCellProps = {
  diffLine: SuggestedFixDiffLine
  children: ReactNode
  isLeftSide?: boolean
}

const DIMMED_LINE_NUMBER_TYPES: DiffLineType[] = ['CONTEXT', 'INJECTED_CONTEXT']

export function LineNumberCell({diffLine, isLeftSide, children}: LineNumberCellProps) {
  return (
    <Cell
      className={clsx('diff-line-number position-relative text-center', {
        'diff-line-number-neutral': DIMMED_LINE_NUMBER_TYPES.includes(diffLine.type),
      })}
      style={{
        backgroundColor: getLineBackgroundColor(diffLine.type, true),
        cursor: 'default',
      }}
      isLeftSide={isLeftSide}
    >
      <code>{children}</code>
    </Cell>
  )
}
