import {Button, Checkbox, IconButton, Label, Link, Banner, Tooltip, Spinner} from '@primer/react'
import React, {type ChangeEvent, useMemo, useState} from 'react'
import {ChevronDownIcon, ChevronRightIcon, ShieldSlashIcon} from '@primer/octicons-react'
import {clsx} from 'clsx'
import type {RuleFinding} from '../types/rule-finding'
import {FindingState} from '../types/rule-finding'
import type {RuleSeverity} from '@github-ui/code-scanning-shared/types/rule-severity'
import {CodeQualitySnippet} from './CodeQualitySnippet'
import {useRuleFindingsAutofixesMutation} from '../hooks/use-rule-findings-autofix-mutation'
import {blobPath, codeQualityRuleFindingsAutofixesCreatePath, codeQualityRuleFindingsPath} from '@github-ui/paths'
import {CommitAutofixButton} from './CommitAutofixButton'
import {CopilotAutofixState} from './CopilotAutofixState'
import {useQueryClient} from '@github-ui/react-query'

import {useRuleFindingsBulkStateMutation} from '../hooks/use-rule-findings-bulk-state-mutation'
import styles from './CodeQualityFileFrame.module.css'
import {SuggestedFixDiff} from './SuggestedFixDiff'

export interface CodeQualityFileFrameProps {
  finding: RuleFinding
  owner: string
  repo: string
  defaultBranch: string
  branchListCacheKey: string
  ruleId: string
  ruleTitle: string
  ruleSeverity: RuleSeverity
  canAutofix: boolean
  canDismiss: boolean
  isDismissed: boolean
  hasRepoWriteAccess: boolean
  isSelected?: boolean
  onSelect?: (selected: boolean) => void
}

export function CodeQualityFileFrame({
  finding: {
    filePath,
    snippetStartLine,
    startLine,
    endLine,
    startColumn,
    endColumn,
    codeSnippetLines,
    number,
    suggestedFix,
    message,
  },
  owner,
  repo,
  defaultBranch,
  branchListCacheKey,
  ruleId,
  ruleTitle,
  ruleSeverity,
  canAutofix,
  canDismiss,
  isDismissed,
  hasRepoWriteAccess,
  isSelected,
  onSelect,
}: CodeQualityFileFrameProps) {
  const queryClient = useQueryClient()
  const [isOpen, setIsOpen] = useState(true)
  const {
    mutate: mutateGenerateFix,
    isSuccess: isGenerateFixSuccess,
    isPending: isGenerateFixPending,
    isError: isGenerateFixError,
    error: generateFixError,
  } = useRuleFindingsAutofixesMutation(
    codeQualityRuleFindingsAutofixesCreatePath({
      owner,
      repo,
      ruleId,
      number,
    }),
  )
  const {
    mutate: mutateBulkFindingState,
    isPending: isFindingStatePending,
    isError: isFindingStateError,
  } = useRuleFindingsBulkStateMutation(codeQualityRuleFindingsPath({owner, repo, ruleId}))

  const isGenerateAutofixDisabled =
    isGenerateFixPending || (isGenerateFixSuccess && suggestedFix === null) || suggestedFix?.state === 'pending'

  const showAutofixState = useMemo(() => {
    if (!canAutofix) return false

    if (suggestedFix) return suggestedFix.state !== 'valid'

    return isGenerateFixSuccess || isGenerateFixError
  }, [canAutofix, suggestedFix, isGenerateFixSuccess, isGenerateFixError])

  const autofixStateMessage = () => {
    if ((isGenerateFixSuccess && !suggestedFix) || suggestedFix?.state === 'pending') {
      return 'is generating a fix suggestion...'
    }
    if (isGenerateFixError) {
      return generateFixError?.message
    }

    return 'could not generate a fix suggestion, please try again later.'
  }

  const onClickGenerateFix = () => {
    if (isGenerateAutofixDisabled) return

    mutateGenerateFix(undefined, {
      onSuccess: () => {
        queryClient.invalidateQueries({
          queryKey: ['rule-findings'],
        })
      },
    })
  }

  const onClickDismissButton = () => {
    const newState = isDismissed ? FindingState.Open : FindingState.Dismissed
    const onSuccess = () => {
      queryClient.invalidateQueries({queryKey: ['rule-findings']})
    }

    mutateBulkFindingState(
      {
        ruleId,
        findings: [{number}],
        state: newState,
      },
      {onSuccess},
    )
  }

  return (
    <div>
      {isFindingStateError && (
        <Banner
          hideTitle
          variant="critical"
          title={`Error ${isDismissed ? 'reopening' : 'dismissing'} the finding`}
          description={`Error when ${isDismissed ? 'reopening' : 'dismissing'} the finding`}
          className="mb-2"
        />
      )}

      <Header
        isOpen={isOpen}
        toggleOpen={() => setIsOpen(v => !v)}
        isSelected={isSelected}
        onSelect={onSelect}
        selectLabel={`Select finding ${filePath}:${startLine}`}
      >
        <div className={styles.headerContent}>
          <div className={styles.headerText}>
            <Link
              href={blobPath({
                owner,
                repo,
                commitish: defaultBranch,
                filePath,
                lineNumber: startLine,
                endLineNumber: endLine,
              })}
              className={styles.codeSnippetLink}
            >
              {filePath}:{startLine}
            </Link>
            {suggestedFix?.state === 'valid' && (
              <Label size="small" variant="secondary" className="ml-2">
                Autofix
              </Label>
            )}
            {isDismissed && (
              <Label size="small" variant="danger" className="ml-2">
                Dismissed
              </Label>
            )}
          </div>
          <div className="d-flex flex-row gap-2 flex-wrap">
            {!isDismissed && canAutofix && suggestedFix?.state !== 'valid' && (
              <Button
                onClick={onClickGenerateFix}
                leadingVisual={isGenerateAutofixDisabled ? <Spinner size="small" /> : undefined}
                aria-disabled={isGenerateAutofixDisabled}
                size="small"
                variant="invisible"
              >
                Generate fix
              </Button>
            )}

            {!isDismissed && canAutofix && suggestedFix?.state === 'valid' && hasRepoWriteAccess && (
              <CommitAutofixButton
                findingNumber={number}
                ruleTitle={ruleTitle}
                owner={owner}
                repo={repo}
                defaultBranch={defaultBranch}
                branchListCacheKey={branchListCacheKey}
              />
            )}

            {canDismiss && (
              <>
                {!isDismissed && !isFindingStatePending ? (
                  <Tooltip text="Dismiss finding">
                    <Button
                      aria-label="Dismiss finding"
                      onClick={onClickDismissButton}
                      leadingVisual={ShieldSlashIcon}
                      size="small"
                      variant="invisible"
                    >
                      {}
                    </Button>
                  </Tooltip>
                ) : (
                  <Button
                    aria-label={isDismissed ? 'Reopen' : undefined}
                    onClick={onClickDismissButton}
                    loading={isFindingStatePending}
                    size="small"
                    variant="invisible"
                  >
                    {isDismissed ? 'Reopen' : undefined}
                  </Button>
                )}
              </>
            )}
          </div>
        </div>
      </Header>

      {showAutofixState && <CopilotAutofixState message={autofixStateMessage()} />}

      {isOpen &&
        (suggestedFix?.state === 'valid' ? (
          <div className={styles.body}>
            <SuggestedFixDiff
              fixFiles={suggestedFix.files}
              filePath={filePath}
              startLine={startLine}
              endLine={endLine}
              startColumn={startColumn}
              endColumn={endColumn}
              borderVariant="none"
            />
          </div>
        ) : (
          <div className={styles.body}>
            {codeSnippetLines.length === 0 ? (
              <div className="flex-column flex-items-center text-center tmp-pt-4 pb-2 px-2">
                <h2 className="f4">Preview unavailable</h2>
                <p className="color-fg-muted">The file content could not be displayed.</p>
              </div>
            ) : (
              <CodeQualitySnippet
                snippetStartLine={snippetStartLine}
                startLine={startLine}
                endLine={endLine}
                startColumn={startColumn}
                endColumn={endColumn}
                codeLines={codeSnippetLines}
                ruleSeverity={ruleSeverity}
                message={message}
              />
            )}
          </div>
        ))}
    </div>
  )
}

function Header(
  props: React.PropsWithChildren<{
    isOpen: boolean
    toggleOpen(): void
    isSelected?: boolean
    onSelect?: (selected: boolean) => void
    selectLabel?: string
  }>,
) {
  const {isOpen, toggleOpen, isSelected, onSelect, selectLabel, children} = props
  const handleCheckboxChange = (e: ChangeEvent<HTMLInputElement>) => {
    e.stopPropagation()
    onSelect?.(e.target.checked)
  }

  return (
    <div className={clsx(styles.header, !isOpen && styles.LegacyHeaderClosed)}>
      {onSelect !== undefined && (
        <Checkbox checked={isSelected ?? false} onChange={handleCheckboxChange} aria-label={selectLabel} />
      )}
      <IconButton
        icon={isOpen ? ChevronDownIcon : ChevronRightIcon}
        onClick={toggleOpen}
        variant="invisible"
        size="small"
        aria-label={`${isOpen ? 'Close' : 'Open'} code snippet`}
      />
      {children}
    </div>
  )
}
