import {useCallback, useMemo} from 'react'
import pluralize from 'pluralize'
import {ChartCard} from '@github-ui/chart-card'
import {number as formatNumber} from '@github-ui/formatters'
import type {OrgCount} from '../types/org-count'
import {Grade, gradeToColor, gradeToFilterValue, gradeToNumber, gradeToText} from '../types/grade'
import {useFilterParams} from '../hooks/use-filter-params'

import styles from './CountsBubbleChart.module.css'
import {addQualifierToQuery, getQualifierFromQuery, removeQualifierFromQuery} from '../utils/filters'

const lowestGrade = (a: Grade, b: Grade) => {
  return gradeToNumber[a] < gradeToNumber[b] ? a : b
}

const categories = Object.entries(gradeToNumber)
  .toSorted(([, a], [, b]) => a - b)
  .map(([grade]) => gradeToText[grade as Grade])
const minValue = Object.values(gradeToNumber).reduce((min, val) => Math.min(min, val), Infinity)
const maxValue = Object.values(gradeToNumber).reduce((max, val) => Math.max(max, val), -Infinity)

function tooltipPointFormatter(this: Highcharts.Point) {
  const counts = (this as unknown as {orgCounts: OrgCount}).orgCounts

  // eslint-disable-next-line github/unescaped-html-literal -- We need to use HTML since Highcharts tooltips use HTML.
  return `<div class="${styles.tooltipTable}">
    <div class="${styles.tooltipTableHeader}">
      ${formatNumber(counts.repositoryCount)} ${pluralize('repository', counts.repositoryCount)}
    </div>
    <div class="${styles.tooltipTableRow}">
      <div>Reliability</div>
      <div class="${styles.tooltipTableValue}">
        <strong>${gradeToText[counts.reliabilityGrade]}</strong>
      </div>
    </div>
    <div class="${styles.tooltipTableRow}">
      <div>Maintainability</div>
      <div class="${styles.tooltipTableValue}">
        <strong>${gradeToText[counts.maintainabilityGrade]}</strong>
      </div>
    </div>
  </table>`
}

export type CountsBubbleChartProps = {
  counts: OrgCount[]
}

export function CountsBubbleChart({counts}: CountsBubbleChartProps) {
  const {manipulateQuery} = useFilterParams()

  const handleBubbleClicked = useCallback(
    (maintainabilityGrade: Grade, reliabilityGrade: Grade) => {
      manipulateQuery(query => {
        let newQuery = query

        const existingMaintainabilityFilters = getQualifierFromQuery(newQuery, 'maintainability-score')
        const existingReliabilityFilters = getQualifierFromQuery(newQuery, 'reliability-score')
        const newMaintainabilityFilter = gradeToFilterValue[maintainabilityGrade]
        const newReliabilityFilter = gradeToFilterValue[reliabilityGrade]

        // If the exact filters are already applied then remove them, otherwise add them
        if (
          existingMaintainabilityFilters.length === 1 &&
          existingMaintainabilityFilters[0] === newMaintainabilityFilter &&
          existingReliabilityFilters.length === 1 &&
          existingReliabilityFilters[0] === newReliabilityFilter
        ) {
          newQuery = removeQualifierFromQuery(newQuery, 'maintainability-score')
          newQuery = removeQualifierFromQuery(newQuery, 'reliability-score')
        } else {
          newQuery = addQualifierToQuery(newQuery, 'maintainability-score', newMaintainabilityFilter)
          newQuery = addQualifierToQuery(newQuery, 'reliability-score', newReliabilityFilter)
        }

        return newQuery
      })
    },
    [manipulateQuery],
  )

  const series = useMemo<Highcharts.SeriesOptionsType[]>(() => {
    return Object.values(Grade).map(grade => {
      return {
        name: gradeToText[grade],
        data: counts
          .filter(count => lowestGrade(count.reliabilityGrade, count.maintainabilityGrade) === grade)
          .map(count => ({
            x: gradeToNumber[count.reliabilityGrade],
            y: gradeToNumber[count.maintainabilityGrade],
            z: count.repositoryCount,
            orgCounts: count,
            events: {
              click: () => {
                handleBubbleClicked(count.maintainabilityGrade, count.reliabilityGrade)
              },
            },
          })),
        color: `var(--bgColor-${gradeToColor[grade]}-muted)`,
        sizeBy: 'area' as const,
        type: 'bubble' as const,
        className: `${styles.dashedMarker} ${styles[`grade-${grade}`]}`,
        marker: {
          lineColor: `var(--borderColor-${gradeToColor[grade]}-emphasis)`,
          lineWidth: 1,
        },
      }
    })
  }, [counts, handleBubbleClicked])

  return (
    <ChartCard size="xl" border padding="normal" visibleControls={false} className="tmp-mb-4">
      <ChartCard.Title>Score distribution across repositories</ChartCard.Title>
      <ChartCard.Description>
        A breakdown of code quality scores across repositories in this organization.
      </ChartCard.Description>
      <ChartCard.Chart
        type="bubble"
        series={series}
        xAxisTitle="Reliability"
        yAxisTitle="Maintainability"
        xAxisOptions={{
          categories,
          gridLineDashStyle: 'Solid',
          tickmarkPlacement: 'on',
          min: minValue,
          max: maxValue,
        }}
        yAxisOptions={{
          categories,
          gridLineDashStyle: 'Solid',
          tickmarkPlacement: 'on',
          startOnTick: false,
          endOnTick: false,
          min: minValue,
          max: maxValue,
        }}
        tooltipOptions={{
          pointFormatter: tooltipPointFormatter,
          headerFormat: '',
          footerFormat: '',
        }}
      />
    </ChartCard>
  )
}
