import {useMutation, type UseMutationResult} from '@github-ui/react-query'
import {fetchJson} from '../utils/fetch-json'

export function useRuleFindingsAutofixesMutation(path: string): UseMutationResult<void, Error, void> {
  return useMutation({
    mutationFn: async () => {
      return fetchJson(path, {
        method: 'POST',
        defaultErrorMessage: 'could not generate a fix suggestion, please try again later.',
      })
    },
  })
}
