import {mainQuery} from '@github-ui/react-core/future/main-query'
import {codeQualityAppBuilder} from '../config/app-builder'

export type CodeQualityAvailability = 'all' | 'selected' | 'none'

export type EnterpriseCodeQualityPoliciesResponse = {
  enterprise_id: number
  enterprise_slug: string
  repo_admins_can_modify_enablement: boolean
  code_quality_availability: CodeQualityAvailability
}

export const enterpriseCodeQualityPoliciesRoute = codeQualityAppBuilder.createQueryRouteConfig(
  'enterpriseCodeQualityPoliciesRoute',
  {
    path: '/enterprises/:business/settings/code_quality_policies',
    queries: [mainQuery<EnterpriseCodeQualityPoliciesResponse>()],
  },
)
