import {DEFAULT_FILTER_TYPE_OPTIONS} from '@github-ui/code-scanning-shared/filter-providers/types'
import type {FilterSuggestion, SuppliedFilterProviderOptions} from '@github-ui/filter'
import {SelectFilterProvider, StaticFilterProvider} from '@github-ui/filter-core/providers'
import {
  CodescanIcon,
  CopilotIcon,
  LockIcon,
  OrganizationIcon,
  RepoIcon,
  ShieldIcon,
  SortDescIcon,
  ToolsIcon,
} from '@primer/octicons-react'
import {Grade, gradeToColor, gradeToFilterValue, gradeToNumber, gradeToText} from '../types/grade'

const gradeFilterValues = Object.values(Grade).map(grade => ({
  value: gradeToFilterValue[grade],
  displayName: gradeToText[grade],
  priority: gradeToNumber[grade],
  iconColor: `var(--bgColor-${gradeToColor[grade]}-emphasis)`,
})) satisfies FilterSuggestion[]

export class ReliabilityScoreFilterProvider extends SelectFilterProvider {
  constructor(options?: SuppliedFilterProviderOptions) {
    super(
      {
        displayName: 'Reliability score',
        key: 'reliability-score',
        priority: 1,
        icon: ShieldIcon,
        description: 'Find repositories with the selected reliability score',
      },
      gradeFilterValues,
      {
        ...options,
        filterTypes: {
          ...DEFAULT_FILTER_TYPE_OPTIONS,
          exclusive: false,
          ...options?.filterTypes,
        },
      },
    )
  }
}

