export class VisibilityFilterProvider extends SelectFilterProvider {
  constructor(options?: SuppliedFilterProviderOptions) {
    super(
      {
        displayName: 'Visibility',
        key: 'visibility',
        priority: 1,
        icon: LockIcon,
        description: 'Find repositories of the selected visibilities',
      },
      [
        {value: 'public', displayName: 'Public', priority: 1, icon: RepoIcon},
        {value: 'internal', displayName: 'Internal', priority: 2, icon: OrganizationIcon},
        {value: 'private', displayName: 'Private', priority: 3, icon: LockIcon},
      ],
      {
        ...options,
        filterTypes: {
          ...DEFAULT_FILTER_TYPE_OPTIONS,
          ...options?.filterTypes,
        },
      },
    )
  }
}

export class StandardFindingsFilterProvider extends StaticFilterProvider {
  constructor(options?: SuppliedFilterProviderOptions) {
    super(
      {
        displayName: 'Standard findings',
        key: 'standard-findings',
        priority: 1,
        icon: CodescanIcon,
        description: 'Find repositories that have standard findings',
      },
      [],
      {
        ...options,
        filterTypes: {
          ...DEFAULT_FILTER_TYPE_OPTIONS,
          // Only has:standard-findings and no:standard-findings are supported
          inclusive: false,
          exclusive: false,
          valueless: true,
          hasValue: true,
          multiKey: false,
          multiValue: false,
          ...options?.filterTypes,
        },
      },
    )
  }
}

