export class SortFilterProvider extends SelectFilterProvider {
  constructor(options?: SuppliedFilterProviderOptions) {
    const filterKeys = {
      displayName: 'Sort',
      key: 'sort',
      priority: 1,
      icon: SortDescIcon,
      description: 'Sort repositories',
    }
    const opts = {
      ...options,
      filterTypes: {
        ...DEFAULT_FILTER_TYPE_OPTIONS,
        exclusive: false,
        multiValue: false,
        ...options?.filterTypes,
      },
    }
    const filterValues = [
      {value: 'last-activity-desc', displayName: 'Recently pushed', priority: 1},
      {value: 'last-activity-asc', displayName: 'Least recently pushed', priority: 2},
      {value: 'repository-name-asc', displayName: 'Repository name ascending', priority: 3},
      {value: 'repository-name-desc', displayName: 'Repository name descending', priority: 4},
      {value: 'reliability-asc', displayName: 'Reliability score ascending', priority: 5},
      {value: 'reliability-desc', displayName: 'Reliability score descending', priority: 6},
      {value: 'maintainability-asc', displayName: 'Maintainability score ascending', priority: 7},
      {value: 'maintainability-desc', displayName: 'Maintainability score descending', priority: 8},
      {value: 'standard-findings-count-asc', displayName: 'Standard findings count ascending', priority: 9},
      {value: 'standard-findings-count-desc', displayName: 'Standard findings count descending', priority: 10},
      {value: 'ai-findings-count-asc', displayName: 'AI findings count ascending', priority: 11},
      {value: 'ai-findings-count-desc', displayName: 'AI findings count descending', priority: 12},
    ]

    super(filterKeys, filterValues, opts)
  }
}
