import {useMemo} from 'react'

import type {SafeHTMLString} from '@github-ui/safe-html'
import {hasHiddenUnicodeCharacters, showHiddenUnicodeCharactersRaw} from '@github-ui/hidden-unicode-banner/utils'
import {showHiddenUnicodeCharactersHTML} from '@github-ui/hidden-unicode-banner/HiddenUnicodeCharacter'
import type {SuggestedFixDiffLine} from '../../types/suggested-fix'
import {DiffLineSide} from './DiffLineSide'
import {groupDiffLines} from './group-diff-lines'

export type SplitDiffLinesProps = {
  diffHasHiddenUnicodeCharacters: boolean
  diffLines: SuggestedFixDiffLine[]
  showHiddenUnicode: boolean
}

export function SplitDiffLines({diffHasHiddenUnicodeCharacters, diffLines, showHiddenUnicode}: SplitDiffLinesProps) {
  const {leftLines, rightLines} = useMemo(() => groupDiffLines(diffLines), [diffLines])

  const processLineForHiddenUnicode = (line: SuggestedFixDiffLine | null): [SuggestedFixDiffLine | null, boolean] => {
    let hasHiddenUnicode = false
    if (diffHasHiddenUnicodeCharacters && line !== null) {
      hasHiddenUnicode = hasHiddenUnicodeCharacters(line.text)

      if (showHiddenUnicode && hasHiddenUnicode) {
        if (line.html) {
          line = {
            ...line,
            /* eslint-disable-next-line @github-ui/github-monorepo/no-cast-as-safe-html-string -- Composed from sanitized segments */
            html: showHiddenUnicodeCharactersHTML(line.html as SafeHTMLString) ?? line.html,
          }
        } else {
          line = {...line, text: showHiddenUnicodeCharactersRaw(line.text)}
        }
      }
    }
    return [line, hasHiddenUnicode]
  }

  const lines: React.ReactNode[] = []
  for (let i = 0; i < leftLines.length; i++) {
    const leftLineBase = leftLines[i] as SuggestedFixDiffLine | null
    const rightLineBase = rightLines[i] as SuggestedFixDiffLine | null

    if (!leftLineBase && !rightLineBase) continue

    const [leftLine, leftLineHasHiddenUnicodeCharacters] = processLineForHiddenUnicode(leftLineBase)
    const [rightLine, rightLineHasHiddenUnicodeCharacters] = processLineForHiddenUnicode(rightLineBase)

    lines.push(
      <tr key={`${leftLine?.left}-${rightLine?.right}`} className="diff-line-row">
        <DiffLineSide diffLine={leftLine} hasHiddenUnicodeCharacters={leftLineHasHiddenUnicodeCharacters} isLeftSide />
        <DiffLineSide diffLine={rightLine} hasHiddenUnicodeCharacters={rightLineHasHiddenUnicodeCharacters} />
      </tr>,
    )
  }

  return <>{lines}</>
}
