export const RuleLanguage = {
  CSharp: 'csharp',
  Go: 'go',
  Java: 'java',
  JavaScript: 'javascript',
  Python: 'python',
  Ruby: 'ruby',
} as const

export type RuleLanguage = (typeof RuleLanguage)[keyof typeof RuleLanguage]

export const RuleLanguageFilterOption = {
  All: 'All',
  CSharp: 'C#',
  Go: 'Go',
  Java: 'Java',
  JavaScript: 'JavaScript',
  Python: 'Python',
  Ruby: 'Ruby',
} as const

export type RuleLanguageFilterOption = (typeof RuleLanguageFilterOption)[keyof typeof RuleLanguageFilterOption]

export const languageOptions: RuleLanguageFilterOption[] = Object.values(RuleLanguageFilterOption)

// Converts a string to RuleLanguage
export function mapLanguageStringToRuleLanguage(language: string | null): RuleLanguage | undefined {
  if (!language) {
    return undefined
  }

  switch (language.toLowerCase()) {
    case RuleLanguage.CSharp:
      return RuleLanguage.CSharp
    case RuleLanguage.Go:
      return RuleLanguage.Go
    case RuleLanguage.Java:
      return RuleLanguage.Java
    case RuleLanguage.JavaScript:
      return RuleLanguage.JavaScript
    case RuleLanguage.Python:
      return RuleLanguage.Python
    case RuleLanguage.Ruby:
      return RuleLanguage.Ruby
    default:
      return undefined
  }
}

export const languageFilterOption: Record<RuleLanguage, RuleLanguageFilterOption> = {
  [RuleLanguage.CSharp]: RuleLanguageFilterOption.CSharp,
  [RuleLanguage.Go]: RuleLanguageFilterOption.Go,
  [RuleLanguage.Java]: RuleLanguageFilterOption.Java,
  [RuleLanguage.JavaScript]: RuleLanguageFilterOption.JavaScript,
  [RuleLanguage.Python]: RuleLanguageFilterOption.Python,
  [RuleLanguage.Ruby]: RuleLanguageFilterOption.Ruby,
}

// Converts a RuleLanguageFilterOption to RuleLanguage
export function mapRuleLanguageFilterOptionToRuleLanguage(option: RuleLanguageFilterOption): RuleLanguage | undefined {
  const ruleLanguage = Object.keys(languageFilterOption).find(
    key => languageFilterOption[key as RuleLanguage] === option,
  )

  return ruleLanguage ? (ruleLanguage as RuleLanguage) : undefined
}

// Converts a string to RuleLanguageFilterOption
export function mapLanguageStringToRuleLanguageFilterOption(language: string | null): RuleLanguageFilterOption {
  const parsedLanguage = mapLanguageStringToRuleLanguage(language)
  if (!parsedLanguage) {
    return RuleLanguageFilterOption.All
  }

  const filterOption = languageFilterOption[parsedLanguage]
  return filterOption || RuleLanguageFilterOption.All
}

// Colours are copied from https://github.com/github-linguist/linguist/blob/main/lib/linguist/languages.yml
// These are the only languages supported by code quality
export const languageColors: Record<RuleLanguage, string> = {
  [RuleLanguage.CSharp]: '#178600',
  [RuleLanguage.Go]: '#00ADD8',
  [RuleLanguage.Java]: '#B07219',
  [RuleLanguage.JavaScript]: '#F1E05A',
  [RuleLanguage.Python]: '#3572A5',
  [RuleLanguage.Ruby]: '#701516',
}

export function getLanguageColor(language: RuleLanguage): string {
  return languageColors[language] || '#EDEDED' // Default to black if language not found
}
