import {registerDataRouterApp} from '@github-ui/react-core/register-app'
import {codeQualityAppBuilder} from './config/app-builder'

import {repoCodeQualityIndexRoute} from './routes/repo-code-quality-index-route'
import {RepoCodeQualityIndex} from './routes/RepoCodeQualityIndex'
import {repoCodeQualityShowRoute} from './routes/repo-code-quality-show-route'
import {RepoCodeQualityShow} from './routes/RepoCodeQualityShow'
import {repoCodeQualitySettingsRoute} from './routes/repo-code-quality-settings-route'
import {RepoCodeQualitySettings} from './routes/RepoCodeQualitySettings'
import {repoCodeQualityAIFindingsRoute} from './routes/repo-code-quality-recent-activity-route'
import {RepoCodeQualityRecentActivity} from './routes/RepoCodeQualityRecentActivity'
import {orgCodeQualityIndexRoute} from './routes/org-code-quality-index-route'
import {OrgCodeQualityIndex} from './routes/OrgCodeQualityIndex'
import {enterpriseCodeQualityPoliciesRoute} from './routes/enterprise-code-quality-policies-route'
import {EnterpriseCodeQualityPolicies} from './routes/EnterpriseCodeQualityPolicies'
import {orgCodeQualitySettingsRoute} from './routes/org-code-quality-settings-route'
import {OrgCodeQualitySettings} from './routes/OrgCodeQualitySettings'

export const codeQualityApp = codeQualityAppBuilder.createDataRouterAppFromRoutes([
  repoCodeQualityIndexRoute.toRoute({Component: RepoCodeQualityIndex}),
  repoCodeQualityShowRoute.toRoute({Component: RepoCodeQualityShow}),
  repoCodeQualitySettingsRoute.toRoute({Component: RepoCodeQualitySettings}),
  repoCodeQualityAIFindingsRoute.toRoute({Component: RepoCodeQualityRecentActivity}),
  orgCodeQualityIndexRoute.toRoute({Component: OrgCodeQualityIndex}),
  orgCodeQualitySettingsRoute.toRoute({Component: OrgCodeQualitySettings}),
  enterpriseCodeQualityPoliciesRoute.toRoute({Component: EnterpriseCodeQualityPolicies}),
])
registerDataRouterApp(codeQualityApp)
