import {ProgressBar} from '@primer/react'
import {Grade} from '../types/grade'
import styles from './MetricProgressBar.module.css'

export interface MetricProgressBarProps {
  grade?: Grade
}

export function MetricProgressBar({grade}: MetricProgressBarProps) {
  const {activeColor, activeCount} = getColors(grade)
  const totalSegments = 4
  const progressPerSegment = 100 / totalSegments

  return (
    <ProgressBar barSize="small" className={styles.ProgressBar} aria-label={`Code quality grade: ${grade}`}>
      {Array.from({length: totalSegments}, (_, i) => (
        <ProgressBar.Item
          key={i}
          bg={i < activeCount ? activeColor : 'neutral.muted'}
          progress={progressPerSegment}
          aria-label={i < activeCount ? 'Progress segment' : 'Inactive segment'}
          aria-valuenow={progressPerSegment}
        />
      ))}
    </ProgressBar>
  )
}

function getColors(g?: Grade) {
  switch (g) {
    case Grade.A:
      return {activeColor: 'success.emphasis', activeCount: 4}
    case Grade.B:
      return {activeColor: 'attention.emphasis', activeCount: 3}
    case Grade.C:
      return {activeColor: 'severe.emphasis', activeCount: 2}
    case Grade.D:
      return {activeColor: 'danger.emphasis', activeCount: 1}
    default:
      return {activeColor: 'neutral.muted', activeCount: 0}
  }
}
