import {useQuery, type UseQueryOptions, type UseQueryResult} from '@github-ui/react-query'
import {fetchJson} from '../utils/fetch-json'
import type {GetRecentFindingsResponse} from '../types/get-recent-findings-response'

export function useRecentFindingsQuery(
  path: string,
  options?: Omit<UseQueryOptions<GetRecentFindingsResponse>, 'queryKey' | 'queryFn'>,
): UseQueryResult<GetRecentFindingsResponse> {
  return useQuery({
    queryKey: ['recent-findings', path],
    queryFn: (): Promise<GetRecentFindingsResponse> => {
      return fetchJson(path)
    },
    ...options,
  })
}
