import {useMutation, type UseMutationResult} from '@github-ui/react-query'
import type {RecentActivityCommitFixResponse} from '../types/recent-activity-commit-fix-response'
import type {RecentActivityCommitFixRequest} from '../types/recent-activity-commit-fix-request'
import {fetchJson} from '../utils/fetch-json'

export function useRecentActivityCommitFixMutation(
  path: string,
): UseMutationResult<RecentActivityCommitFixResponse, Error, RecentActivityCommitFixRequest> {
  return useMutation({
    mutationKey: ['recent-activity-commit-fix', path],
    mutationFn: async request => {
      const response = await fetchJson<RecentActivityCommitFixResponse>(path, {
        method: 'POST',
        body: {
          name: request.name,
          create_new_branch: request.createNewBranch,
          create_draft_pr: request.createDraftPR,
          fixes: request.fixes.map(fix => ({
            file_path: fix.filePath,
            diff_content: fix.diffContent,
          })),
        },
      })
      return response
    },
  })
}
