import React from 'react'
import type {SuggestedFixFile} from '../types/suggested-fix'
import {CodeQualityDiff} from './CodeQualityDiff'

export type SuggestedFixDiffProps = {
  fixFiles: SuggestedFixFile[]
  filePath: string
  startLine: number
  endLine: number
  startColumn: number
  endColumn: number
  borderVariant?: 'rounded' | 'none'
}

export function SuggestedFixDiff({
  fixFiles,
  filePath,
  startLine,
  endLine,
  startColumn,
  endColumn,
  borderVariant = 'rounded',
}: SuggestedFixDiffProps) {
  return (
    <>
      {fixFiles
        .filter(file => file.filePath === filePath)
        .map(file => (
          <React.Fragment key={file.filePath}>
            {file.diffEntries.map(diffEntry => (
              <CodeQualityDiff
                key={diffEntry.path}
                diffEntry={diffEntry}
                startLine={startLine}
                endLine={endLine}
                startColumn={startColumn}
                endColumn={endColumn}
                borderVariant={borderVariant}
              />
            ))}
          </React.Fragment>
        ))}
    </>
  )
}
