import {useRouteQuery} from '@github-ui/react-core/future/use-route-query'
import {Banner, Heading, ToggleSwitch, Link} from '@primer/react'
import {orgCodeQualitySettingsRoute} from './org-code-quality-settings-route'
import {BetaLabel} from '@github-ui/lifecycle-labels/beta'
import {useCallback, useState} from 'react'
import {useToggleOrgCodeQualityOnReposMutation} from '../hooks/use-toggle-org-code-quality-on-repos-mutation'
import {EnableCodeQualityConfirmationDialog} from '../components/EnableCodeQualityConfirmationDialog'

import styles from './OrgCodeQualitySettings.module.css'

export function OrgCodeQualitySettings() {
  const {
    data: {org, orgName, enabled, repoCount},
  } = useRouteQuery(orgCodeQualitySettingsRoute, 'mainQuery')

  const [isEnabled, setIsEnabled] = useState(enabled)
  const [showConfirmDialog, setShowConfirmDialog] = useState(false)
  const toggleMutation = useToggleOrgCodeQualityOnReposMutation()

  const handleToggle = useCallback(
    (on: boolean) => {
      toggleMutation.mutate(
        {org, enabled: on},
        {
          onSuccess: response => {
            setIsEnabled(response.enabled)
          },
        },
      )
    },
    [org, toggleMutation],
  )

  const handleToggleClick = useCallback(() => {
    if (isEnabled) {
      handleToggle(false)
    } else {
      setShowConfirmDialog(true)
    }
  }, [isEnabled, handleToggle])

  const handleDialogClose = useCallback(
    (gesture: 'confirm' | 'cancel' | 'close-button' | 'escape') => {
      if (gesture === 'confirm') {
        handleToggle(true)
      }
      setShowConfirmDialog(false)
    },
    [handleToggle],
  )

  return (
    <>
      <div className="Subhead">
        <Heading as="h2" className="Subhead-heading d-flex gap-2 flex-items-center">
          Code quality <BetaLabel />
        </Heading>

        <p className="color-fg-muted">
          Find and fix code quality issues like code coverage, maintainability risks, reliability problems, and more.
          Get quality insights directly in your development workflow with Copilot-powered autofix.
        </p>
      </div>

      <div role="alert" aria-atomic="true">
        {toggleMutation.isError && (
          <Banner
            title="Enablement failed"
            description={toggleMutation.error.message}
            variant="critical"
            className="mt-3"
          />
        )}
      </div>

      <div className="d-flex flex-column gap-3 mt-3">
        <div className={styles.settingsGroupContainer}>
          <div className={styles.settingRowWithNoBorder}>
            <div>
              <div id="enable-code-quality-repos-label" className="text-bold">
                Enable Code Quality
              </div>
              <div className="color-fg-muted text-small tmp-mt-1">
                Enable Code Quality for all repositories in <strong>{orgName}</strong> organization.
              </div>
            </div>
            <ToggleSwitch
              aria-labelledby="enable-code-quality-repos-label"
              size="small"
              checked={isEnabled}
              disabled={toggleMutation.isPending}
              loading={toggleMutation.isPending}
              onClick={handleToggleClick}
              statusLabelPosition="end"
            />
          </div>
        </div>

        <Banner variant="info" title={isEnabled ? 'Code Quality Enabled' : 'Code Quality Disabled'} hideTitle>
          {/* The original copy includes the following but we don't have the data to support it yet.
        We can add back in when we have the data to support it. */}
          {/* Go to Security and quality &gt; Overview to track and enforce quality for pull requests across your repositories. */}
          {isEnabled ? (
            <div>
              Code Quality is enabled for your organization. See{' '}
              <Link href="https://docs.github.com/en/code-security/concepts/about-code-quality" inline>
                Code Quality docs
              </Link>{' '}
              to learn more.
            </div>
          ) : (
            <div>
              Enabling Code Quality will run CodeQL analysis on pull requests and pushes, and add Copilot as a reviewer
              to pull requests. This will incur charges in Actions minutes. See{' '}
              <Link href="https://docs.github.com/en/code-security/concepts/about-code-quality" inline>
                Code Quality docs
              </Link>
              .
            </div>
          )}
        </Banner>
      </div>

      {showConfirmDialog && <EnableCodeQualityConfirmationDialog repoCount={repoCount} onClose={handleDialogClose} />}
    </>
  )
}
