import {useState, useEffect} from 'react'
import {ActionList, ActionMenu, Heading, Pagination, Spinner, TextInput} from '@primer/react'
import {SearchIcon} from '@primer/octicons-react'
import {GitHubAvatar} from '@github-ui/github-avatar'
import {useEnterpriseOrganizations, type Organization} from '../hooks/use-enterprise-organizations'

interface OrgSelectionListProps {
  enterpriseSlug: string
  onOrgToggle: (orgId: number, allowed: boolean) => void
  updatingOrgId?: number | null
}

export function OrgSelectionList({enterpriseSlug, onOrgToggle, updatingOrgId = null}: OrgSelectionListProps) {
  const [query, setQuery] = useState('')
  const [debouncedQuery, setDebouncedQuery] = useState('')
  const [page, setPage] = useState(1)

  useEffect(() => {
    const timeoutId = setTimeout(() => {
      setDebouncedQuery(query)
      setPage(1)
    }, 300)
    return () => clearTimeout(timeoutId)
  }, [query])

  const {data, isLoading, isError} = useEnterpriseOrganizations({enterpriseSlug, page, query: debouncedQuery})

  if (isError) {
    return <p className="tmp-p-3 text-center color-fg-danger">Failed to load organizations. Please try again.</p>
  }

  return (
    <div className="tmp-mt-3 border rounded-2">
      <div className="tmp-p-3 border-bottom">
        <Heading as="h3" className="f6 mb-2">
          Select organizations
        </Heading>
        <TextInput
          leadingVisual={SearchIcon}
          placeholder="Search organizations..."
          value={query}
          onChange={e => setQuery(e.target.value)}
          aria-label="Search organizations"
          className="width-full"
        />
      </div>

      {isLoading ? (
        <div className="tmp-p-4 text-center">
          <Spinner size="medium" />
        </div>
      ) : (
        <>
          <ul className="list-style-none m-0 p-0">
            {data?.organizations.map((org: Organization) => (
              <OrgRow
                key={org.id}
                org={org}
                onToggle={onOrgToggle}
                isUpdating={updatingOrgId === org.id}
                disabled={updatingOrgId !== null}
              />
            ))}
          </ul>

          {data && data.total_pages > 1 && (
            <div className="tmp-p-3 border-top d-flex flex-justify-center">
              <Pagination
                pageCount={data.total_pages}
                currentPage={page}
                onPageChange={(_e, newPage) => setPage(newPage)}
              />
            </div>
          )}

          {data?.organizations.length === 0 && (
            <p className="tmp-p-4 text-center color-fg-muted">No organizations found.</p>
          )}
        </>
      )}
    </div>
  )
}

function OrgRow({
  org,
  onToggle,
  isUpdating,
  disabled,
}: {
  org: Organization
  onToggle: (id: number, allowed: boolean) => void
  isUpdating: boolean
  disabled: boolean
}) {
  return (
    <li className="d-flex flex-items-center flex-justify-between tmp-p-3 border-bottom">
      <div className="d-flex flex-items-center gap-2">
        <GitHubAvatar src={org.avatar_url} size={32} alt={`${org.login} avatar`} />
        <span className="text-bold">{org.login}</span>
      </div>
      <ActionMenu>
        <ActionMenu.Button disabled={disabled} size="small">
          {isUpdating && <Spinner size="small" />}
          <span>{org.allowed ? 'Available' : 'Not available'}</span>
        </ActionMenu.Button>
        <ActionMenu.Overlay>
          <ActionList selectionVariant="single">
            <ActionList.Item selected={org.allowed} onSelect={() => onToggle(org.id, true)}>
              Available
              <ActionList.Description>Code Quality can be enabled for this organization.</ActionList.Description>
            </ActionList.Item>
            <ActionList.Item selected={!org.allowed} onSelect={() => onToggle(org.id, false)}>
              Not available
              <ActionList.Description>Code Quality cannot be enabled for this organization.</ActionList.Description>
            </ActionList.Item>
          </ActionList>
        </ActionMenu.Overlay>
      </ActionMenu>
    </li>
  )
}
