import {SortAscIcon, SortDescIcon} from '@primer/octicons-react'
import {ActionList, ActionMenu} from '@primer/react'
import {SORT_FIELD_LABELS, SORT_FIELDS, type RuleSortField, type RuleSortDirection} from '../types/rule-sort'

export interface RuleSortMenuProps {
  sortField: RuleSortField
  sortDirection: RuleSortDirection
  onSortFieldChange: (field: RuleSortField) => void
  onSortDirectionChange: (direction: RuleSortDirection) => void
}

export function RuleSortMenu({sortField, sortDirection, onSortFieldChange, onSortDirectionChange}: RuleSortMenuProps) {
  const buttonLabel = SORT_FIELD_LABELS[sortField]

  return (
    <ActionMenu>
      <ActionMenu.Button variant="invisible" leadingVisual={sortDirection === 'asc' ? SortAscIcon : SortDescIcon}>
        {buttonLabel}
      </ActionMenu.Button>

      <ActionMenu.Overlay>
        <ActionList selectionVariant="single">
          <ActionList.Group>
            <ActionList.GroupHeading>Sort by</ActionList.GroupHeading>
            {SORT_FIELDS.map(field => (
              <ActionList.Item key={field} selected={sortField === field} onSelect={() => onSortFieldChange(field)}>
                {SORT_FIELD_LABELS[field]}
              </ActionList.Item>
            ))}
          </ActionList.Group>
          <ActionList.Group>
            <ActionList.GroupHeading>Order</ActionList.GroupHeading>
            <ActionList.Item selected={sortDirection === 'asc'} onSelect={() => onSortDirectionChange('asc')}>
              <ActionList.LeadingVisual>
                <SortAscIcon />
              </ActionList.LeadingVisual>
              Ascending
            </ActionList.Item>
            <ActionList.Item selected={sortDirection === 'desc'} onSelect={() => onSortDirectionChange('desc')}>
              <ActionList.LeadingVisual>
                <SortDescIcon />
              </ActionList.LeadingVisual>
              Descending
            </ActionList.Item>
          </ActionList.Group>
        </ActionList>
      </ActionMenu.Overlay>
    </ActionMenu>
  )
}
