import {useRouteQuery} from '@github-ui/react-core/future/use-route-query'
import {repoCodeQualityIndexRoute} from './repo-code-quality-index-route'
import {RepoCodeQualityDisabled} from '../components/RepoCodeQualityDisabled'
import {RepoCodeQualityEnabled} from '../components/RepoCodeQualityEnabled'

export function RepoCodeQualityIndex() {
  const {data} = useRouteQuery(repoCodeQualityIndexRoute, 'mainQuery')

  if (data.enabled ?? true) {
    const {
      owner,
      repo,
      branch,
      lastScanAt,
      maintainability,
      reliability,
      recentActivityEnabled,
      recentSuggestionsCount,
      codeQualityDocsUrls,
    } = data

    return (
      <RepoCodeQualityEnabled
        owner={owner}
        repo={repo}
        branch={branch}
        lastScanAt={lastScanAt}
        maintainability={maintainability}
        reliability={reliability}
        recentActivityEnabled={recentActivityEnabled}
        recentSuggestionsCount={recentSuggestionsCount}
        codeQualityDocsUrls={codeQualityDocsUrls}
      />
    )
  }
  const {owner, repo, codeQualityDocsUrls, readonly, blockedByPolicy} = data
  return (
    <RepoCodeQualityDisabled
      owner={owner}
      repo={repo}
      codeQualityDocsUrls={codeQualityDocsUrls}
      readonly={readonly}
      blockedByPolicy={blockedByPolicy}
    />
  )
}
