export const RuleCategory = {
  Maintainability: 'maintainability',
  Reliability: 'reliability',
} as const

export type RuleCategory = (typeof RuleCategory)[keyof typeof RuleCategory]

export const RuleCategoryFilterOption = {
  All: 'All',
  Maintainability: 'Maintainability',
  Reliability: 'Reliability',
} as const

export type RuleCategoryFilterOption = (typeof RuleCategoryFilterOption)[keyof typeof RuleCategoryFilterOption]

export const ruleCategoryOptions: RuleCategoryFilterOption[] = Object.values(RuleCategoryFilterOption)

export function parseRuleCategory(category: string | null): RuleCategoryFilterOption {
  if (!category) {
    return RuleCategoryFilterOption.All
  }

  switch (category.toLowerCase()) {
    case RuleCategory.Reliability:
      return RuleCategoryFilterOption.Reliability
    case RuleCategory.Maintainability:
      return RuleCategoryFilterOption.Maintainability
    default:
      return RuleCategoryFilterOption.All
  }
}
