import React from 'react'
import type {SafeHTMLString} from '@github-ui/safe-html'
import {VerifiedHTMLText} from '@github-ui/safe-html/VerifiedHTML'
import {clsx} from 'clsx'
import {normalizedStartColumn} from '../utils/normalized-start-column'
import type {RuleSeverity} from '@github-ui/code-scanning-shared/types/rule-severity'
import styles from './CodeQualitySnippet.module.css'

export interface CodeQualitySnippetProps {
  snippetStartLine: number
  startLine: number
  endLine: number
  startColumn: number
  endColumn: number
  codeLines: SafeHTMLString[]
  ruleSeverity: RuleSeverity
  message?: SafeHTMLString
}

export function CodeQualitySnippet({
  snippetStartLine,
  startLine,
  endLine,
  startColumn,
  endColumn,
  codeLines,
  ruleSeverity,
  message,
}: CodeQualitySnippetProps) {
  return (
    <div itemProp="text" data-testid="blob-wrapper" className="blob-wrapper">
      <table
        aria-label="Code quality code snippet"
        className="js-highlight-code-snippet-columns p-2"
        data-start-line={startLine}
        data-end-line={endLine}
        data-start-column={normalizedStartColumn(startColumn, endColumn)}
        data-end-column={endColumn}
      >
        <tbody aria-label="Code quality location code snippet lines">
          {codeLines.map((line, index) => {
            const lineNumber = snippetStartLine + index
            if (line.length === 0) {
              /* eslint-disable-next-line @github-ui/github-monorepo/no-cast-as-safe-html-string -- Static string literal is safe */
              line = '\n' as SafeHTMLString
            }

            const row = (
              <tr key={lineNumber}>
                <td
                  id={`L${lineNumber}`}
                  className={`${styles.lineNumber} tmp-pl-3 blob-num color-fg-subtle`}
                  data-line-number={lineNumber}
                  data-testid={`line-number-${lineNumber}`}
                />
                <td
                  id={`LC${lineNumber}`}
                  className={`${styles.wrapper} blob-code blob-code-inner`}
                  data-testid={`code-line-${lineNumber}`}
                >
                  <VerifiedHTMLText html={line} data-line-number-content={lineNumber} />
                </td>
              </tr>
            )

            if (lineNumber === endLine && message) {
              return (
                <React.Fragment key={lineNumber}>
                  {row}
                  <tr>
                    <td colSpan={2} className="p-0">
                      <FindingAnnotation message={message} ruleSeverity={ruleSeverity} />
                    </td>
                  </tr>
                </React.Fragment>
              )
            }

            return row
          })}
        </tbody>
      </table>
    </div>
  )
}

function annotationBorderClass(severity: RuleSeverity): string {
  switch (severity) {
    case 'warning':
    case 'medium':
      return styles.annotationBorderWarning
    case 'error':
    case 'high':
    case 'critical':
    case 'failure':
      return styles.annotationBorderDanger
    default:
      return styles.annotationBorderDefault
  }
}

function FindingAnnotation({message, ruleSeverity}: {message: SafeHTMLString; ruleSeverity: RuleSeverity}) {
  return (
    <div className={clsx(styles.annotation, annotationBorderClass(ruleSeverity))}>
      <VerifiedHTMLText html={message} />
      <div className={styles.codeqlLabel}>CodeQL</div>
    </div>
  )
}
