// eslint-disable-next-line @github-ui/github-monorepo/restrict-relay-imports
import {getLineBackgroundColor, lineNeedsMarkerPadding, trimDiffLineHtml} from '@github-ui/diff-lines/line-helpers'
import type {SafeHTMLString} from '@github-ui/safe-html'
import {VerifiedHTMLDiv} from '@github-ui/safe-html/VerifiedHTML'
import {NoEntryIcon} from '@primer/octicons-react'
import {clsx} from 'clsx'
import {useMemo} from 'react'
import type {SuggestedFixDiffLine} from '../../types/suggested-fix'
import {Cell} from './Cell'

export type ContentCellProps = {
  diffLine: SuggestedFixDiffLine
  isLeftSide?: boolean
}

export function ContentCell({diffLine, isLeftSide}: ContentCellProps) {
  const [lineHtml, lineTypeCharacter] = trimDiffLineHtml(diffLine.html, diffLine.type)
  const showLineTypeCharacter = lineTypeCharacter && ['+', '-'].includes(lineTypeCharacter)

  const lineHasMarkerPadding = useMemo(() => lineNeedsMarkerPadding(diffLine), [diffLine])

  return (
    <Cell
      className={clsx('diff-text-cell tmp-pr-4', isLeftSide ? 'left-side-diff-cell' : 'right-side-diff-cell', {
        'tmp-pt-4': lineHasMarkerPadding,
        'border-right': isLeftSide && diffLine.type !== 'HUNK',
      })}
      style={{
        backgroundColor: getLineBackgroundColor(diffLine.type, false),
      }}
      isLeftSide={isLeftSide}
    >
      <code
        className={clsx('diff-text syntax-highlighted-line', {
          addition: diffLine.type === 'ADDITION',
          deletion: diffLine.type === 'DELETION',
        })}
      >
        {showLineTypeCharacter && <span className="diff-text-marker">{lineTypeCharacter}</span>}
        {/* Explicitly mark html as safe because it is server-sanitized */}
        <VerifiedHTMLDiv
          /* eslint-disable-next-line @github-ui/github-monorepo/no-cast-as-safe-html-string -- HTML is sanitized server-side. TODO: Move type assertion to data ingress point. */
          html={lineHtml as SafeHTMLString}
          className={clsx('diff-text-inner', {
            'color-fg-muted': diffLine.type === 'HUNK',
          })}
          id={isLeftSide ? `LC${diffLine.left}` : undefined}
          data-line-number-content={isLeftSide ? diffLine.left : undefined}
        />
        {diffLine.displayNoNewLineWarning && <NoEntryIcon size={16} className="fgColor-danger" />}
      </code>
    </Cell>
  )
}
