import {useState, useTransition} from 'react'
import type {AiFileFindings, AiFinding} from '../types/ai-findings'
import {blobPath} from '@github-ui/paths'
import {clsx} from 'clsx'
import styles from './RecentActivityFindingsFile.module.css'
import {
  BranchName,
  Checkbox,
  CounterLabel,
  FormControl,
  Label,
  RelativeTime,
  Dialog,
  Button,
  IconButton,
  Stack,
} from '@primer/react'
import {SuggestedFixDiff} from './SuggestedFixDiff'
import {RecentActivityCommitFixButton} from './RecentActivityCommitFixButton'
import {RecentActivityFindingsCopilotNotEnabledDialog} from './RecentActivityFindingsCopilotNotEnabledDialog'
import {XIcon, LinkExternalIcon} from '@primer/octicons-react'

export type RecentActivityFindingsFileProps = {
  owner: string
  repo: string
  branch: string
  file: AiFileFindings
  hasNewFindings: boolean
  selected: boolean
  onSelectionChange: (selected: boolean) => void
  onFixWithCopilot: () => void
  isPrBeingCreated: boolean
  copilotSWEAgentEnabled: boolean
  copilotCodingAgentDocsUrl: string
  branchListCacheKey: string
  hasRepoWriteAccess: boolean
}

export function RecentActivityFindingsFile({
  owner,
  repo,
  branch,
  file,
  hasNewFindings,
  selected,
  onSelectionChange,
  onFixWithCopilot,
  isPrBeingCreated,
  copilotSWEAgentEnabled,
  copilotCodingAgentDocsUrl,
  branchListCacheKey,
  hasRepoWriteAccess,
}: RecentActivityFindingsFileProps) {
  const [, startTransition] = useTransition()
  const [expanded, setExpanded] = useState(false)
  const [isClosing, setIsClosing] = useState(false)
  const [showCopilotNotEnabledDialog, setShowCopilotNotEnabledDialog] = useState(false)
  const fileLinkHref = blobPath({
    owner,
    repo,
    commitish: file.commitOid,
    filePath: file.filePath,
  })

  if (file.findings.length === 0) {
    return null
  }

  function handleClose() {
    setIsClosing(true)
    // Wait for animation to complete before actually closing
    setTimeout(() => {
      setExpanded(false)
      setIsClosing(false)
    }, 300) // Adjust timing to match your CSS transition duration
  }

  function handleCloseWithDelay() {
    // Keep modal open for a moment before starting the closing animation
    setTimeout(() => {
      handleClose()
    }, 2000) // Wait 2 seconds before starting to close
  }

  function handleFixWithCopilot() {
    if (!copilotSWEAgentEnabled) {
      setShowCopilotNotEnabledDialog(true)
      return
    }

    onFixWithCopilot()
    handleCloseWithDelay()
  }

  return (
    <>
      <div className={clsx(styles.fileHeader, 'Box-row')}>
        {hasRepoWriteAccess && (
          <FormControl className="mr-2">
            <Checkbox checked={selected} onChange={() => onSelectionChange(!selected)} />
            <FormControl.Label visuallyHidden>Select file: {file.filePath}</FormControl.Label>
          </FormControl>
        )}
        <Button
          variant="link"
          onClick={() => {
            startTransition(() => {
              setExpanded(true)
            })
          }}
          aria-label={`Expand ${file.filePath}`}
          className={styles.filePathButton}
        >
          {file.filePath}
        </Button>
        <CounterLabel>{file.findings.length}</CounterLabel>
        {hasNewFindings && (
          <span>
            <Label variant="accent">New</Label>
          </span>
        )}
        <div className={clsx(styles.fileMetadata, !hasRepoWriteAccess && styles.fileMetadataNoCheckbox)}>
          Last push <RelativeTime date={new Date(file.lastPushAt)} /> to <BranchName as="span">{branch}</BranchName>
        </div>
      </div>

      {expanded && (
        <Dialog
          onClose={handleClose}
          position="right"
          className={clsx(styles.dialog, isClosing && styles.dialogClosing)}
          renderHeader={() => (
            <div className={styles.dialogHeader}>
              <Stack direction="vertical" className={styles.dialogHeaderMeta}>
                <div className={styles.dialogTitleWrapper}>
                  <h3 className={styles.dialogTitle}>{file.filePath}</h3>
                </div>
                <div className={styles.fileMetadata}>
                  Last push <RelativeTime date={new Date(file.lastPushAt)} /> to{' '}
                  <BranchName as="span">{branch}</BranchName>
                </div>
              </Stack>
              <Stack gap="condensed" direction="horizontal">
                <IconButton
                  as="a"
                  role="link"
                  href={fileLinkHref}
                  icon={LinkExternalIcon}
                  aria-label={`Open file in new page`}
                  variant="invisible"
                  size="small"
                  target="_blank"
                />
                <IconButton
                  icon={XIcon}
                  aria-label="Close dialog"
                  onClick={handleClose}
                  variant="invisible"
                  size="small"
                />
              </Stack>
            </div>
          )}
        >
          <Stack direction="vertical" gap="normal">
            <Stack direction="horizontal" justify="space-between" align="center">
              <h4 className={styles.findingsTitle}>
                {file.findings.length} <span>{file.findings.length === 1 ? 'finding' : 'findings'}</span>
              </h4>
              {hasRepoWriteAccess && (
                <RecentActivityCommitFixButton
                  suggestedFixFiles={file.findings.map(f => f.fixFiles).flat()}
                  owner={owner}
                  repo={repo}
                  defaultBranch={branch}
                  branchListCacheKey={branchListCacheKey}
                  onFixWithCopilot={handleFixWithCopilot}
                  isPrBeingCreated={isPrBeingCreated}
                  testId="sidepanel-commit-fix-button"
                />
              )}
            </Stack>
            {[...file.findings].sort(compareFindings).map(finding => {
              const key = `${file.filePath}:${finding.message}:${finding.startLine}:${finding.startColumn}`
              return <Finding key={key} finding={finding} filePath={file.filePath} />
            })}
          </Stack>
        </Dialog>
      )}

      {showCopilotNotEnabledDialog && (
        <RecentActivityFindingsCopilotNotEnabledDialog
          copilotCodingAgentDocsUrl={copilotCodingAgentDocsUrl}
          showFixWithoutCopilotButton
          suggestedFixFiles={file.findings.flatMap(f => f.fixFiles)}
          owner={owner}
          repo={repo}
          branch={branch}
          branchListCacheKey={branchListCacheKey}
          onClose={() => setShowCopilotNotEnabledDialog(false)}
        />
      )}
    </>
  )
}

function Finding({finding, filePath}: {finding: AiFinding; filePath: string}) {
  return (
    <div>
      <div className="py-2">{finding.message}</div>
      <SuggestedFixDiff
        fixFiles={finding.fixFiles}
        filePath={filePath}
        startLine={finding.startLine}
        endLine={finding.endLine}
        startColumn={finding.startColumn}
        endColumn={finding.endColumn}
        borderVariant="rounded"
      />
    </div>
  )
}

function compareFindings(a: AiFinding, b: AiFinding): number {
  if (a.startLine !== b.startLine) {
    return a.startLine - b.startLine
  }

  if (a.startColumn !== b.startColumn) {
    return a.startColumn - b.startColumn
  }

  return 0
}
