import {useQuery} from '@github-ui/react-query'
import {fetchJson} from '../utils/fetch-json'
import type {GetRulesRequest} from '../types/get-rules-request'
import {addGetRulesRequestToPath} from '../types/get-rules-request'
import type {GetRulesResponse} from '../types/get-rules-response'

export function useRulesQuery(path: string, request: GetRulesRequest) {
  return useQuery<GetRulesResponse>({
    queryKey: ['rules', path, request],
    queryFn: () => {
      return fetchJson(addGetRulesRequestToPath(path, request))
    },
  })
}
